#!/usr/bin/env node
// Bundles the workspace and public-site Workers with esbuild into ESM strings the wizard
// uploads through the Cloudflare API. Output: wizard/src/generated/bundles.ts (gitignored).
import { build } from "esbuild";
import { readFileSync, mkdirSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const workers = resolve(here, "..");

async function bundle(entry) {
  const result = await build({
    entryPoints: [join(workers, entry)],
    bundle: true,
    write: false,
    format: "esm",
    platform: "neutral",
    target: "es2022",
    mainFields: ["module", "main"],
    conditions: ["workerd", "worker", "import", "browser"],
    minify: false,
    legalComments: "none",
  });
  return result.outputFiles[0].text;
}

const workspace = await bundle("workspace/src/index.ts");
const publicSite = await bundle("public-site/src/index.ts");
const migrationsDir = join(workers, "workspace", "migrations");
const migrations = readdirSync(migrationsDir)
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .map((name) => ({ name, sql: readFileSync(join(migrationsDir, name), "utf8") }));

const out = join(workers, "wizard", "src", "generated", "bundles.ts");
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  "// GENERATED by workers/scripts/build-workspace-bundle.mjs. Do not edit or commit.\n" +
    "export const WORKSPACE_BUNDLE: string = " + JSON.stringify(workspace) + ";\n" +
    "export const PUBLIC_SITE_BUNDLE: string = " + JSON.stringify(publicSite) + ";\n" +
    "export const WORKSPACE_MIGRATIONS: { name: string; sql: string }[] = " + JSON.stringify(migrations) + ";\n" +
    "export const BUNDLE_BUILT_AT: string = " + JSON.stringify(new Date().toISOString()) + ";\n",
);
console.log(`bundles: workspace ${(workspace.length / 1024).toFixed(0)} KiB, public-site ${(publicSite.length / 1024).toFixed(0)} KiB, ${migrations.length} migration(s) -> ${out}`);
